/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderLineV2Entity))]
final class METPurchPurchaseOrderLineV2Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        METInventItemOrderSetup     metInventItemOrderSetup;        
        InventItemBarcode           inventItemBarcode;

        
        changecompany(this.DataAreaId)
        {
            /// CB871_CB872 Sales returns . Get unit in shipcase during purchase order line export
            this.METUnitInShipCase = METCalcWMSFactor::construct().getUnitinShipCaseFactor(this.ItemNumber, this.METPurchLineInventDimId);

            select firstonly TempRcvLimit 
                from metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == this.ItemNumber
                && metInventItemOrderSetup.SiteId == this.ReceivingSiteId;

            this.METPOLineTempRcvLimit = metInventItemOrderSetup.TempRcvLimit ? metInventItemOrderSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

            this.METPOLineInventoryUOM = InventTableModule::find(this.ItemNumber,ModuleInventPurchSales::Invent).UnitId;

            if(this.RecId)
            {
                purchLine metpurchLine;

                select firstonly RecId, CurrencyCode from metpurchLine
                    where metpurchLine.InventTransId == this.InventoryLotId
                       && !metpurchLine.IsDeleted;

                if(metpurchLine.RecId)
                {
                    this.METPOlineTaxAmount = Tax::calcTaxAmount(this.SalesTaxGroupCode, this.SalesTaxItemGroupCode,
                                            DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                            metpurchLine.CurrencyCode, this.LineAmount, TaxModuleType::Purch);
                }

                PurchLine purchLineLcoal = PurchLine::findInventTransId(this.InventoryLotId);

                this.METPOLineReceiptWarehouseQty = purchLineLcoal.metReceiptedWarehouseQty();
                this.METReceivedInTotal = purchLineLcoal.receivedInTotal(); 
            }

            //get the default barcode
            select firstonly ItemBarCode from inventItemBarcode
                where inventItemBarcode.itemId == this.ItemNumber
                   && inventItemBarcode.UnitID == this.PurchaseUnitSymbol
                   && inventItemBarcode.METDefault == NoYes::Yes;

            this.METPOLineConfPurchGTIN = inventItemBarcode.itemBarCode;
            //VM - CB754 - Excise Register fields addition
            this.METName = InventTable::find(this.ItemNumber).itemName(); 
        }
        next postload();
    }

/// <summary>
/// CoC method for InsertEntityDataSource method
/// </summary>
/// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
/// <returns>true of false</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, METPurchLine))
    {
        PurchLine purchLine = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, PurchLine)).getBuffer();
        _dataSourceCtx.setBuffer(METPurchLine::find(purchLine.RecId, true));
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
        this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
    }
    
    boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    return ret;
}

    /// <summary>
    /// Finds record buffer for data source and return
    /// </summary>
    /// <param name = "_entityCtx">Entity context</param>
    /// <param name = "_dataSourceCtx">Data source runtime context</param>
    /// <returns>Record buffer associated with data source</returns>
    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, METPurchLine))
        {
            ret = METPurchLine::find(this.METPurchLineRecid);
        }

        return ret;
    }

    /// <summary>
    /// Post target process method to approve the purchase orders once all the lines are imported
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">Type DefinitionGroupExecution</param>
    public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        PurchPurchaseOrderLineV2Staging    metStaging;
        DMFEntity                          dmfEntity, dmfParentEntity;

        select firstonly RecId, ParentEntityName from dmfEntity
                where dmfEntity.EntityName == _dmfDefinitionGroupExecution.Entity
            exists join dmfParentEntity
                where dmfParentEntity.EntityName == dmfEntity.ParentEntityName
                   && dmfParentEntity.EntityType == DMFEntityTypes::CompositEntity;
         
        if (dmfEntity.RecId) //Execute only for composite entities
        {
            // Check if processing of all records are completed
            select firstonly RecId
                    from metStaging
                    where metStaging.DefinitionGroup    == _dmfDefinitionGroupExecution.DefinitionGroup
                        && metStaging.ExecutionId       == _dmfDefinitionGroupExecution.ExecutionId
                        && metStaging.TransferStatus    != DMFTransferStatus::Completed
                        && metStaging.TransferStatus    != DMFTransferStatus::Duplicate
                        && metStaging.TransferStatus    != DMFTransferStatus::Error;

            if (!metStaging.RecId)
            {
                PurchPurchaseOrderHeaderV2Entity::metProcessDataForCompositeEntity(_dmfDefinitionGroupExecution);                
            } 
        }

        PurchLine   purchLine;
        PurchTable  purchTable;
        
         while select metStaging
            group by metStaging.PurchaseOrderNumber
            where metStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                && metStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                && metStaging.TransferStatus == DMFTransferStatus::Completed
            exists join purchTable
                where purchTable.PurchId == metStaging.PurchaseOrderNumber
                && (!purchTable.METIntercompanyTransferReplenishment
                    || purchTable.InterCompanyOrigin != InterCompanyOrigin::Derived)
           
        { 
            PurchPurchaseOrderLineV2Staging    metStagingLine;

            ttsbegin;

            while select forupdate purchLine
                join metStagingLine
                where metStagingLine.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                    && metStagingLine.ExecutionId    == _dmfDefinitionGroupExecution.ExecutionId
                    && metStagingLine.TransferStatus == DMFTransferStatus::Completed
                    && metStagingLine.PurchaseOrderNumber == purchTable.PurchId
                    && purchLine.PurchId    == metStagingLine.PurchaseOrderNumber
                    && purchLine.ItemId     == metStagingLine.ItemNumber
                    && purchLine.LineNumber == metStagingLine.LineNumber
            {
                PurchPrice  importedPrice       = purchLine.PurchPrice;
                LineAmount  importedLineAmount  = purchLine.LineAmount;
                DiscPct     importedLinePercent = purchLine.LinePercent;
                AmountCur   importedLineDisc    = purchLine.LineDisc;

                if (metStagingLine.PurchaseUnitSymbol)
                {
                    purchLine.PurchUnit = metStagingLine.PurchaseUnitSymbol;
                }
                else
                {
                    purchLine.modifiedField(fieldNum(PurchLine, ItemId));
                }
                purchLine.modifiedField(fieldNum(PurchLine, PurchUnit));
                PurchLine::modifyPurchQty(purchLine, purchLine.inventDim());

                if (importedPrice && purchLine.PurchPrice == 0)
                {
                    purchLine.PurchPrice  = importedPrice;
                    purchLine.LineAmount  = importedLineAmount;
                    purchLine.LinePercent = importedLinePercent;
                    purchLine.LineDisc    = importedLineDisc;
                }
                purchLine.update();
            }
            ttscommit;
        }
        // Update PurchTable manual submission flag after processing the purchase order lines
        PurchPurchaseOrderLineV2Entity::postTargetProcessUpdatePurchTable(_dmfDefinitionGroupExecution);
    }

    /// <summary>
    /// Update PurchTable manual submission flag after processing the purchase order lines
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">DMFDefinitionGroupExecution</param>
    private static void postTargetProcessUpdatePurchTable(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        PurchPurchaseOrderLineV2Staging     metStaging;
        METPurchTable                       metPurchTable;

        while select PurchaseOrderNumber
            from metStaging
            group by PurchaseOrderNumber
            where metStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
               && metStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId 
               && metStaging.TransferStatus == DMFTransferStatus::Completed
        {             
            metPurchTable = METPurchTable::find(metStaging.PurchaseOrderNumber, true);

            if (metPurchTable.RecId)
            {
                metPurchTable.skipBusinessEvents(true);          
 
                ttsbegin;
                metPurchTable.setSubmissionFlag();
                metPurchTable.doUpdate();
                ttscommit;
            }
            else
            {                
                error(strFmt("@DataExpansionTool:ErrMsg_RecordDoesNotExist_2", metStaging.PurchaseOrderNumber, '@MET:METPurchTableLabel'));
            }
        }
    }

    /// <summary>
    /// Method used to determine and perform new initialization of certain fields of underlying PurchLine datasource as when the order is intercompany replenish fulfillment enabled.
    /// </summary>
    /// <param name = "_entityCtx">Object of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Object of type DataEntityDataSourceRuntimeContext</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, PurchLine)
            && _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
        {
            PurchLine purchLine = _dataSourceCtx.getBuffer();
            PurchTable purchTable = PurchTable::find(purchLine.PurchId);

            if (purchTable.METIntercompanyTransferReplenishment || purchTable.InterCompanyOrigin == InterCompanyOrigin::Derived)
            {
                [purchLine.BarCode, purchLine.BarCodeType] = purchLine.metGetBarCodeForIntercompanyPurchLines(null);
                purchLine.PurchPrice = purchLine.metGetUnitPriceForIntercompanyPurchLines(null); 
                purchLine.LineAmount = purchLine.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
                _dataSourceCtx.setBuffer(purchLine);
            }
            else
            {
                InventItemBarcode inventItemBarcode = InventItemBarcode::metFindPurchBarcodeDimension(purchLine.ItemId, purchLine.inventDim(), '', purchLine.PurchUnit, purchLine.VendAccount);

                purchLine.BarCode        = inventItemBarcode.ItemBarCode;
                purchLine.BarCodeType    = inventItemBarcode.BarcodeSetupId; 

                _dataSourceCtx.setBuffer(purchLine);
            }
        }
        else  if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, METPurchLine)
            && _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
        {
            METPurchLine            metPurchLine = _dataSourceCtx.getBuffer();

            if (!metPurchLine.PurchaseWMSFactor)
            {
                PurchLine               purchLine = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, PurchLine)).getBuffer();
                METInventLocation       metInventLocation;
                InventLocation          inventLocation;
                InventDim               inventDim;

                select firstonly ExternalWMSUnit from metInventLocation
                exists join inventLocation
                    where inventLocation.RecId == metInventLocation.InventLocation
                exists join inventDim
                    where inventDim.inventDimId == purchLine.InventDimId &&
                          inventDim.InventLocationId == inventLocation.InventLocationId;

                metPurchLine.PurchaseWMSFactor =  METPurchTableFormEventHandler::processPurchaseWMSFactor(metInventLocation.ExternalWMSUnit, purchLine);
                _dataSourceCtx.setBuffer(metPurchLine);
            }
        }
    }
